template<> uint32_t TSGrowableArray<CELLIST>::CalcChunkSize(uint32_t nCount) {
    uint32_t nPrev;
    if (nCount < 8) {
      uint32_t nMasked;
      nPrev = nCount - 1 & nCount;
      while (true) {
        nMasked = nPrev;
        if (!nMasked) {
          break;
        }

        nCount = nMasked;
        nPrev = nMasked - 1 & nMasked;
      }

      if (nCount < 1) {
        return 1;
      }
    } else {
      this->m_chunk = 8;
      nCount = 8;
    }

    return nCount;
}

